int lsb_index(uint32_t x) {
    if (!x) return -1;
    int i = 0;
    while ((x & 1) == 0) {
        x >>= 1;
        ++i;
    }
    return i;
}

int main() {
    uint32_t v = 0b10110000;
    printf("lsb index = %d\n", lsb_index(v));
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int msb_index(uint32_t x) {
    if (!x) return -1;
    int i = 31;
    while (((x >> i) & 1) == 0) --i;
    return i;
}

int main() {
    uint32_t v = 0x00f00010;
    printf("msb index = %d\n", msb_index(v));
    return 0;
}

