char* to_binary_str(uint32_t x, char *buf, size_t n) {
    if (n < 33) return NULL;
    for (int i = 31; i >= 0; --i) {
        buf[31-i] = (x & (1u << i)) ? '1' : '0';
    }
    buf[32] = '\0';
    return buf;
}

int main() {
    uint32_t v = 37;
    char b[33];
    printf("%u -> %s\n", v, to_binary_str(v, b, sizeof(b)));
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <ctype.h>

uint32_t parse_hex_u32(const char *s) {
    if (s[0]=='0' && (s[1]=='x' || s[1]=='X')) s += 2;
    uint32_t v = 0;
    while (*s) {
        char c = *s++;
        uint32_t d;
        if (c>='0' && c<='9') d = c-'0';
        else if (c>='a' && c<='f') d = 10 + c-'a';
        else if (c>='A' && c<='F') d = 10 + c-'A';
        else break;
        v = (v<<4) | d;
    }
    return v;
}

int main() {
    printf("0xFF -> %u\n", parse_hex_u32("0xFF"));
    return 0;
}

#include <stdio.h>
#include <stdint.h>

uint32_t align_pow2(uint32_t x) {
    if (x == 0) return 1;
    --x;
    x |= x >> 1;
    x |= x >> 2;
    x |= x >> 4;
    x |= x >> 8;
    x |= x >> 16;
    ++x;
    return x ? x : 0;
}

int main() {
    printf("align_pow2(37) = %u\n", align_pow2(37));
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int is_pow2(uint32_t x) {
    return x && ((x & (x - 1)) == 0);
}

int main() {
    printf("is_pow2(64) = %d\n", is_pow2(64));
    printf("is_pow2(70) = %d\n", is_pow2(70));
    return 0;
}
